// SwiftCodeHighlighter: the five regex passes, in order, over a 30-line
// generated-source sample. Later rules override earlier ones on the same
// characters (strings and comments win over keywords and numbers), exactly
// like `addAttribute(.foregroundColor:)` in the Swift.

import { describe, expect, it } from 'vitest';
import { CodeTheme, SwiftCodeHighlighter, applyColorPass } from '../GeneratedSourcePreview';

const SAMPLE = `//
//  HomeView.swift
//  Generated by AgenticDesigner
//

import SwiftUI

struct HomeView: View {
    @State private var count: Int = 0
    @Binding var title: String
    let greeting = "Hello, world"

    var body: some View {
        VStack(spacing: 16) {
            Text(greeting)
                .font(.system(size: 24, weight: .bold))
            Button("Tap me") {
                count += 1
            }
            if count > 3 {
                Text("Done \\(count) times")   // interpolation, not a keyword
            } else {
                Text("Keep going")
            }
        }
        .padding(20)
    }
}
`;

function spans(code: string): [string, string][] {
  return applyColorPass(code, true).map((token) => [code.slice(token.start, token.end), token.color]);
}

describe('SwiftCodeHighlighter', () => {
  it('tokenises a generated view', () => {
    expect(spans(SAMPLE)).toMatchSnapshot();
  });

  it('colours keywords, types, numbers, strings and comments', () => {
    const tokens = spans(SAMPLE);
    const colorOf = (text: string): string | undefined => tokens.find((t) => t[0] === text)?.[1];
    expect(colorOf('import')).toBe(CodeTheme.keyword);
    expect(colorOf('struct')).toBe(CodeTheme.keyword);
    expect(colorOf('@State')).toBe(CodeTheme.keyword);
    expect(colorOf('SwiftUI')).toBe(CodeTheme.typeName);
    expect(colorOf('Int')).toBe(CodeTheme.typeName);
    expect(colorOf('16')).toBe(CodeTheme.number);
    expect(colorOf('"Hello, world"')).toBe(CodeTheme.string);
    // A comment wins over everything it contains ("not", "a", "keyword").
    expect(colorOf('// interpolation, not a keyword')).toBe(CodeTheme.comment);
    // The `let` inside a string must NOT be a keyword span.
    expect(tokens.some((t) => t[0] === '"Keep going"' && t[1] === CodeTheme.string)).toBe(true);
  });

  it('renders non-Swift files plain', () => {
    expect(applyColorPass('# Readme\n\nfor let struct\n', false)).toEqual([]);
  });

  it('caches by file, isSwift and content hash', () => {
    const first = SwiftCodeHighlighter.attributedCode(SAMPLE, true, 'Sources/App/HomeView.swift');
    const second = SwiftCodeHighlighter.attributedCode(SAMPLE, true, 'Sources/App/HomeView.swift');
    expect(second).toBe(first);
    const edited = SwiftCodeHighlighter.attributedCode(SAMPLE + '\n', true, 'Sources/App/HomeView.swift');
    expect(edited).not.toBe(first);
    expect(SwiftCodeHighlighter.rehighlight(SAMPLE, true).tokens).toEqual(first.tokens);
  });
});
